// Wrap splits text into lines of at most `width` characters, breaking only at spaces.
// A word longer than width goes on a line of its own. Runs of whitespace collapse;
// no line begins or ends with a space. Empty or whitespace-only input returns nil.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}

	fields := strings.Fields(text)
	if len(fields) == 0 {
		return nil
	}

	lines := []string{fields[0]}
	for _, w := range fields[1:] {
		// If adding this word exceeds width, start a new line.
		if len(lines[len(lines)-1])+1+len(w) > width {
			lines = append(lines, w)
		} else {
			lines[len(lines)-1] += " " + w
		}
	}
	return lines
}

