package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		input string
		width int
		want  []string
	}{
		// Basic wrapping at spaces.
		{"hello world foo bar", 10, []string{"hello", "world foo", "bar"}},
		// Runs of whitespace collapse; no leading/trailing spaces.
		{"  hello    world  ", 20, []string{"hello world"}},
		// Empty input returns empty slice (not one empty string).
		{"", 10, nil},
		// Whitespace-only input returns empty slice.
		{"   \t\n  ", 10, nil},
		// Width zero or less returns nil.
		{"hello", 0, nil},
		{"hello", -5, nil},
		// Word longer than width goes on its own line.
		{"superlongword short", 8, []string{"superlongword", "short"}},
		// Multiple long words.
		{"abc defghijk", 4, []string{"abc", "defghijk"}},
		// Single word fits exactly.
		{"hello", 5, []string{"hello"}},
		// Single word just over width.
		{"hello", 4, []string{"hello"}},
		// All words fit on one line.
		{"a b c d", 20, []string{"a b c d"}},
		// Words that exactly fill lines.
		{"hello world", 11, []string{"hello world"}},
	}

	for _, tc := range tests {
		got := Wrap(tc.input, tc.width)
		// Compare nil vs empty slice correctly.
		if len(got) == 0 && len(tc.want) == 0 {
			continue
		}
		if len(got) != len(tc.want) {
			t.Fatalf("Wrap(%q, %d): got %v (%d), want %v (%d)",
				tc.input, tc.width, got, len(got), tc.want, len(tc.want))
		}
		for i, g := range got {
			if g != tc.want[i] {
				t.Errorf("Wrap(%q, %d)[%d]: got %q, want %q",
					tc.input, tc.width, i, g, tc.want[i])
			}
		}
	}
}

